export default async ({ files, parentId, previous }, context) => {
  const state = previous ?? { index: 0, notes: [] };
  let index = state.index;
  while (
    index < files.length &&
    (await context.state.get("notion:" + parentId + ":" + files[index].id))
  )
    index++;
  const file = files[index] ?? null;
  return {
    file,
    more: file !== null,
    endpoint: file ? "/files/" + file.id : "/files/unused",
    state: { index, notes: state.notes },
    notes: state.notes,
  };
};

