function inspectAudio(data, mediaType, file, sha256, spec) {
  const head = String.fromCharCode(...data.subarray(0, 16));
  const ext = file.extension;
  const compatible =
    ext === "wav"
      ? head.startsWith("RIFF") && head.slice(8, 12) === "WAVE"
      : ext === "flac"
        ? head.startsWith("fLaC")
        : ext === "ogg"
          ? head.startsWith("OggS")
          : ext === "webm"
            ? data[0] === 0x1a && data[1] === 0x45 && data[2] === 0xdf && data[3] === 0xa3
            : ext === "mp4" || ext === "m4a"
              ? head.slice(4, 8) === "ftyp"
              : head.startsWith("ID3") || (data[0] === 255 && (data[1] & 224) === 224);
  const type = String(mediaType ?? "")
    .split(";")[0]
    .toLowerCase();
  if (
    !compatible ||
    data.length !== file.size ||
    (type !== "application/octet-stream" &&
      type !== file.mime &&
      spec(type, file.filename) !== file.extension) ||
    (file.sha256 !== null && file.sha256 !== sha256)
  )
    throw Error("The downloaded audio did not match the selected Drive file.");
}

function audioSpec(mime, name) {
  const types = {
    "audio/mpeg": ["mp3", "mpeg", "mpga"],
    "audio/mp3": ["mp3"],
    "audio/mp4": ["m4a", "mp4"],
    "audio/x-m4a": ["m4a"],
    "audio/m4a": ["m4a"],
    "audio/flac": ["flac"],
    "audio/x-flac": ["flac"],
    "audio/ogg": ["ogg"],
    "application/ogg": ["ogg"],
    "audio/wav": ["wav"],
    "audio/x-wav": ["wav"],
    "audio/vnd.wave": ["wav"],
    "audio/webm": ["webm"],
  };
  const extensions = types[mime];
  if (!extensions) return null;
  const suffix = String(name ?? "")
    .split(".")
    .at(-1)
    .toLowerCase();
  return extensions.includes(suffix) ? suffix : extensions[0];
}

export default async ({ audio, file, status }, context) => {
  if (status !== 200 || audio.size !== file.size)
    throw Error("Drive did not return the original audio file.");
  const bytes = await context.artifact.open(audio);
  inspectAudio(
    bytes,
    audio.mediaType,
    file,
    audio.digest.startsWith("sha256:") ? audio.digest.slice(7) : null,
    audioSpec,
  );
  return {
    audio: await context.artifact.put(bytes, { name: file.filename, mediaType: file.mime }),
  };
};

