function normalizeNotionParent(value) {
  if (typeof value !== "string") throw Error("Set the Notion parent page ID.");
  const id = value.replace(/-/g, "").toLowerCase();
  if (!/^[0-9a-f]{32}$/.test(id)) throw Error("Set the Notion parent page ID.");
  return [id.slice(0, 8), id.slice(8, 12), id.slice(12, 16), id.slice(16, 20), id.slice(20)].join(
    "-",
  );
}

function checkNotionNote(page, parentId, file, expectedTitle, normalize) {
  if (
    page?.object !== "page" ||
    page.parent?.type !== "page_id" ||
    normalize(page.parent.page_id) !== parentId
  )
    throw Error("Notion did not confirm a child page under the configured parent.");
  const title = Object.values(page.properties ?? {}).find((property) => property?.type === "title");
  if (
    !Array.isArray(title?.title) ||
    title.title.map((part) => part.plain_text ?? part.text?.content ?? "").join("") !==
      expectedTitle
  ) {
    throw Error("Notion did not confirm the expected recording title.");
  }
  return { fileId: file.id, pageId: normalize(page.id) };
}

export default async ({ file, note, parentId }, context) => {
  const key = "notion:" + parentId + ":" + file.id;
  if (!(await context.state.insert(key, { status: "pending" }))) return { result: null };
  const page = await context.actions.call("notion.create_page", { parentId, ...note });
  const result = checkNotionNote(page, parentId, file, note.title, normalizeNotionParent);
  await context.state.set(key, { status: "confirmed", ...result });
  return { result };
};

